sp_widget.css:
.plumhub-footer {
  background-color: #003366; /* Deep blue */
  color: #ffffff;
  padding: 30px 20px;
  border-top: 4px solid #A5F1F7; /* Aqua border */
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
}

.footer-content {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  max-width: 1200px;
  margin: 0 auto;
  align-items: center;
}

.footer-left h2 {
  margin: 0;
  font-size: 1.8rem;
  color: #A5F1F7;
}

.footer-left p {
  margin-top: 5px;
  font-size: 0.95rem;
}

.footer-right a {
  margin-left: 20px;
  color: #A5F1F7;
  text-decoration: none;
  font-size: 0.95rem;
}

.footer-right a:hover {
  text-decoration: underline;
}

@media (max-width: 768px) {
  .footer-content {
    flex-direction: column;
    text-align: center;
  }

  .footer-right a {
    display: block;
    margin: 10px 0;
  }
}
